let tangled (x : int) : int =
  if x > 0 then 1 else
  if x > 1 then 1 else
  if x > 2 then 1 else
  if x > 3 then 1 else
  if x > 4 then 1 else
  if x > 5 then 1 else
  if x > 6 then 1 else
  if x > 7 then 1 else
  if x > 8 then 1 else
  if x > 9 then 1 else
  if x > 10 then 1 else
  if x > 11 then 1 else
  if x > 12 then 1 else
  if x > 13 then 1 else
  if x > 14 then 1 else
  if x > 15 then 1 else
  0
